function readAll(paths) {                       // async = CPS + trampoline
  return Promise.all(paths.map(p => fs.promises.readFile(p)))
    .then(bufs => bufs.map(String))     // continuation applied on resolve
    .then(lines => lines.join('\n'));
}

function* take(n) {                  // multi-shot continuation: re-entered per next()
  for (let i = 0; i < n; i++) yield i;
}
const g = take(3); g.next(); g.next();
